/**
 * The ports of the platform an open hands to the core: the network, the encrypted session and what it stores and reports.
 */
public struct OpenPorts {
    public var transport: Transport?
    public var encrypted: EncryptedConfig?
    public var credentials: CredentialStore?
    public var http: EncryptedHttp?
    /**
     * The GraphQL address of a database without an encrypted session.
     */
    public var endpoint: String?
    /**
     * The HTTP and socket executor of the platform: the core takes the transport and the encrypted http from it.
     */
    public var executor: Transport?
    /**
     * Android below API 34 runs the upload round in a foreground service of type `dataSync`: `Some(declared)` says whether the manifest of the app declares its permission. `None` where the platform needs no declaration.
     */
    public var dataSyncDeclared: Bool?
    /**
     * The platform reader and writer of the prepare step: a source with `prepare` is refused without it.
     */
    public var preparer: Preparer?
    /**
     * Test stands set it: the database accepts a registration that leaves out an operation the library sends by itself. The `open` of an app never sets it.
     */
    public var partialOperations: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(transport: Transport?, encrypted: EncryptedConfig?, credentials: CredentialStore?, http: EncryptedHttp?, 
        /**
         * The GraphQL address of a database without an encrypted session.
         */endpoint: String? = nil, 
        /**
         * The HTTP and socket executor of the platform: the core takes the transport and the encrypted http from it.
         */executor: Transport? = nil, 
        /**
         * Android below API 34 runs the upload round in a foreground service of type `dataSync`: `Some(declared)` says whether the manifest of the app declares its permission. `None` where the platform needs no declaration.
         */dataSyncDeclared: Bool? = nil, 
        /**
         * The platform reader and writer of the prepare step: a source with `prepare` is refused without it.
         */preparer: Preparer? = nil, 
        /**
         * Test stands set it: the database accepts a registration that leaves out an operation the library sends by itself. The `open` of an app never sets it.
         */partialOperations: Bool = false) {
        self.transport = transport
        self.encrypted = encrypted
        self.credentials = credentials
        self.http = http
        self.endpoint = endpoint
        self.executor = executor
        self.dataSyncDeclared = dataSyncDeclared
        self.preparer = preparer
        self.partialOperations = partialOperations
    }

    

    
}

