/**
 * One test on the rows. A scalar value is a `Cell` of the kinds `Null`, `Bool`, `Int`, `Real` and `Text`.
 */

public indirect enum QueryCondition: Equatable, Hashable {
    
    case equal(field: String, value: Cell
    )
    case notEqual(field: String, value: Cell
    )
    case compare(field: String, op: CompareOp, value: Cell
    )
    case inList(field: String, values: [Cell]
    )
    case notInList(field: String, values: [Cell]
    )
    case isNull(field: String
    )
    case allOf(clauses: [QueryCondition]
    )
    case anyOf(clauses: [QueryCondition]
    )
    case not(clause: QueryCondition
    )
    case search(text: String, wholeWords: Bool
    )





}

#if compiler(>=6)
extension QueryCondition: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeQueryCondition: FfiConverterRustBuffer {
    typealias SwiftType = QueryCondition

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> QueryCondition {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .equal(field: try FfiConverterString.read(from: &buf), value: try FfiConverterTypeCell.read(from: &buf)
        )
        
        case 2: return .notEqual(field: try FfiConverterString.read(from: &buf), value: try FfiConverterTypeCell.read(from: &buf)
        )
        
        case 3: return .compare(field: try FfiConverterString.read(from: &buf), op: try FfiConverterTypeCompareOp.read(from: &buf), value: try FfiConverterTypeCell.read(from: &buf)
        )
        
        case 4: return .inList(field: try FfiConverterString.read(from: &buf), values: try FfiConverterSequenceTypeCell.read(from: &buf)
        )
        
        case 5: return .notInList(field: try FfiConverterString.read(from: &buf), values: try FfiConverterSequenceTypeCell.read(from: &buf)
        )
        
        case 6: return .isNull(field: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .allOf(clauses: try FfiConverterSequenceTypeQueryCondition.read(from: &buf)
        )
        
        case 8: return .anyOf(clauses: try FfiConverterSequenceTypeQueryCondition.read(from: &buf)
        )
        
        case 9: return .not(clause: try FfiConverterTypeQueryCondition.read(from: &buf)
        )
        
        case 10: return .search(text: try FfiConverterString.read(from: &buf), wholeWords: try FfiConverterBool.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: QueryCondition, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .equal(field,value):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(field, into: &buf)
            FfiConverterTypeCell.write(value, into: &buf)
            
        
        case let .notEqual(field,value):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(field, into: &buf)
            FfiConverterTypeCell.write(value, into: &buf)
            
        
        case let .compare(field,op,value):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(field, into: &buf)
            FfiConverterTypeCompareOp.write(op, into: &buf)
            FfiConverterTypeCell.write(value, into: &buf)
            
        
        case let .inList(field,values):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(field, into: &buf)
            FfiConverterSequenceTypeCell.write(values, into: &buf)
            
        
        case let .notInList(field,values):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(field, into: &buf)
            FfiConverterSequenceTypeCell.write(values, into: &buf)
            
        
        case let .isNull(field):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(field, into: &buf)
            
        
        case let .allOf(clauses):
            writeInt(&buf, Int32(7))
            FfiConverterSequenceTypeQueryCondition.write(clauses, into: &buf)
            
        
        case let .anyOf(clauses):
            writeInt(&buf, Int32(8))
            FfiConverterSequenceTypeQueryCondition.write(clauses, into: &buf)
            
        
        case let .not(clause):
            writeInt(&buf, Int32(9))
            FfiConverterTypeQueryCondition.write(clause, into: &buf)
            
        
        case let .search(text,wholeWords):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(text, into: &buf)
            FfiConverterBool.write(wholeWords, into: &buf)
            
        }
    }
