 * What a stream reads.
 */

public enum ReadRequest: Equatable, Hashable {
    
    case list(query: QuerySpec
    )
    case count(query: QuerySpec
    )
    case entity(model: String, id: String, fetch: ReadFetch
    )
    /**
     * The events of a model after the stream opened.
     */
    case events(model: String
    )
    case cableCloses
    /**
     * Each request that leaves for the network with its reason.
     */
    case requests
    /**
     * The status of the transfer of `uploads[action]` of a row.
     */
    case blob(model: String, id: String, action: String
    )
    /**
     * The queue of operations of the database.
     */
    case operations
    case changes





}

