public enum ReadValue: Equatable, Hashable {
    
    /**
     * The whole result at a revision: the first value of a stream of rows.
     */
    case snapshot(revision: Int64, rows: [WireRow], edits: [RowEdit], state: ReadState
    )
    /**
     * The change after the last value the reader took: the steps from the rows it holds to the rows of `revision`.
     */
    case delta(base: Int64, revision: Int64, edits: [RowEdit], state: ReadState
    )
    case count(revision: Int64, count: UInt64, state: ReadState
    )
    /**
     * The whole queue of operations at a revision.
     */
    case operations(revision: Int64, items: [OperationInfo]
    )
    case state(revision: Int64, state: ReadState
    )
    case ready
    case changes(revision: Int64, rows: [ChangedRow]
    )
    /**
     * One event of a model: the rows before and after its landing, read only while a stream of events is open.
     */
    case event(position: UInt64, area: String, kind: String, id: String, before: WireRow?, after: WireRow?
    )
    case cableClose(position: UInt64, event: CableClose
    )
    /**
     * One request that left for the network, read only while a `requests` stream is open.
     */
    case request(operation: String, variablesJson: String, reason: RequestReason
    )
    case lost(first: UInt64, last: UInt64
    )
    case gap
    /**
     * The status of one transfer: the value of the row of the same transfer, at the revision of the stream.
     */
    case status(revision: Int64, upload: WireUpload
    )
    /**
     * The last value of a stream, exactly one.
     */
    case ended(cause: EndCause
    )





}

